/**
 * Detach every destination from `readable`, including destinations that are
 * (re)attached synchronously from an 'unpipe' handler.
 *
 * `readable.unpipe()` with no argument detaches all current destinations, but a
 * destination can pipe the source again while its 'unpipe' event is handled.
 * Re-running until no new 'pipe' events fire guarantees the reader ends up
 * fully detached.
 *
 * @param {import('node:stream').Readable} readable
 * @returns {number} number of unpipe passes performed
 */
export function unpipeAll(readable) {
  const MAX_PASSES = 1000
  const rePiped = []
  const onPipe = (destination) => rePiped.push(destination)

  readable.on('pipe', onPipe)
  try {
    let passes = 0
    do {
      rePiped.length = 0
      readable.unpipe()
      passes += 1
    } while (rePiped.length > 0 && passes < MAX_PASSES)

    if (rePiped.length > 0) {
      throw new Error('unpipeAll: destinations keep re-piping; aborting to avoid an infinite loop')
    }
    return passes
  } finally {
    readable.removeListener('pipe', onPipe)
  }
}
```

