    if (req.method === 'POST' && req.url === '/detach') {
      const passes = detachAll()
      res.writeHead(200, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ detached: true, passes }))
      return
    }

    res.writeHead(404).end()
