```js
Readable.prototype.unpipe = function(dest) {
  const state = this._readableState;
  const { pipes } = state;

  // If we're not piping anywhere, then do nothing.
  if (pipes.length === 0) return this;

  // If no destination, then unpipe everything.
  if (dest === undefined) {
    for (let i = 0; i < pipes.length; i++) {
      const dest = pipes[i];
      dest.emit('unpipe', this, { hasUnpiped: false });
    }

    // Remove all pipes.
    state.pipes = [];
    return this;
  }

  // If we can't find the destination, then do nothing.
  if (!pipes.includes(dest)) return this;

  // Otherwise remove this destination from the list.
  state.pipes = pipes.filter((d) => d !== dest);

  dest.emit('unpipe', this, { hasUnpiped: false });

  return this;
};
