/**
 * Detach every destination from a readable stream.
 *
 * `readable.unpipe()` with no argument detaches all current destinations, but a
 * destination may synchronously re-pipe the source from its own 'unpipe'
 * handler. That re-piped destination is then active but was not part of the
 * original drain, so a single `unpipe()` call is not enough to guarantee the
 * stream ends up fully detached.
 *
 * Keep draining until no destinations remain, with a hard cap so a destination
 * that re-pipes on every 'unpipe' cannot wedge the process in an infinite loop.
 *
 * @param {import('node:stream').Readable} readable
 * @param {{ maxPasses?: number }} [options]
 * @returns {number} the number of drain passes performed
 */
export function unpipeAll(readable, { maxPasses = 1000 } = {}) {
  if (!readable || typeof readable.unpipe !== 'function') {
    throw new TypeError('unpipeAll expects a readable stream')
  }

  const state = readable._readableState
  let passes = 0

  do {
    readable.unpipe()
    passes += 1

    if (passes > maxPasses) {
      throw new Error(
        `unpipeAll: destinations kept re-piping after ${maxPasses} attempts`,
      )
    }
  } while (Array.isArray(state?.pipes) && state.pipes.length > 0)

  return passes
}
```

