import http from 'node:http'
import { PassThrough } from 'node:stream'
import { unpipeAll } from './unpipe.js'

export function createApp() {
  const broadcast = new PassThrough()
  const destinations = new Set()

  function addDestination(res) {
    destinations.add(res)
    broadcast.pipe(res, { end: false })
    res.on('close', () => {
      destinations.delete(res)
      broadcast.unpipe(res)
    })
    return res
  }

  function detachAll() {
    const passes = unpipeAll(broadcast)
    destinations.clear()
    return passes
  }

  const server = http.createServer(async (req, res) => {
    const { pathname } = new URL(req.url, 'http://localhost')

    if (req.method === 'GET' && pathname === '/health') {
      res.writeHead(200, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ destinations: destinations.size }))
      return
    }

    if (req.method === 'GET' && pathname === '/stream') {
      res.writeHead(200, {
        'content-type': 'text/plain; charset=utf-8',
        'cache-control': 'no-cache',
        connection: 'keep-alive',
      })
      addDestination(res)
      return
    }

    if (req.method === 'POST' && pathname === '/publish') {
      const chunks = []
      for await (const chunk of req) chunks.push(chunk)
      broadcast.write(Buffer.concat(chunks))
      res.writeHead(202, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ published: true, destinations: destinations.size }))
      return
    }

    if (req.method === 'POST' && pathname === '/detach') {
      const passes = detachAll()
      res.writeHead(200, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ detached: true, passes }))
      return
    }

    res.writeHead(404, { 'content-type': 'application/json' })
    res.end(JSON.stringify({ error: 'not found' }))
  })

  server.on('close', () => detachAll())

  return { server, broadcast, destinations, detachAll }
}

export function start(port = 0) {
  const app = createApp()
  return new Promise((resolve) => {
    app.server.listen(port, () => resolve({ ...app, port: app.server.address().port }))
  })
}

const isMain = process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href
if (isMain) {
  const port = Number(process.env.PORT) || 3000
  const app = createApp()
  app.server.listen(port, () => {
    console.log(`listening on http://localhost:${port}`)
  })
  const shutdown = () => {
    app.detachAll()
    app.server.close(() => process.exit(0))
  }
  process.on('SIGINT', shutdown)
  process.on('SIGTERM', shutdown)
}
```

