{
  "name": "stream-fanout-server",
  "version": "1.0.0",
  "private": true,
  "description": "Node.js server that reliably unpipes a shared stream from all of its destinations",
  "type": "module",
  "main": "src/server.js",
  "scripts": {
    "start": "node src/server.js",
    "test": "node --test test/"
  },
  "engines": {
    "node": ">=18"
  }
}

/**
 * Detach every destination currently piped from `readable`.
 *
 * `readable.unpipe()` with no argument detaches all *current* destinations, but
 * a destination can synchronously re-pipe the source from its own `unpipe`
 * handler. That newly attached destination is active again, so a single
 * `unpipe()` call does not guarantee the stream ends up fully detached.
 *
 * Keep draining until no destinations remain. A hard cap turns a destination
 * that re-pipes on every `unpipe` into a loud error instead of an infinite loop.
 *
 * @param {import('node:stream').Readable} readable
 * @param {{ maxPasses?: number }} [options]
 * @returns {number} the number of drain passes performed
 */
export function unpipeAll(readable, { maxPasses = 1000 } = {}) {
  if (!readable || typeof readable.unpipe !== 'function') {
    throw new TypeError('unpipeAll expects a readable stream')
  }

  const state = readable._readableState
  let passes = 0

  for (;;) {
    readable.unpipe()
    passes += 1

    if (!Array.isArray(state?.pipes) || state.pipes.length === 0) {
      return passes
    }

    if (passes >= maxPasses) {
      throw new Error(
        `unpipeAll: destinations kept re-piping after ${maxPasses} attempts`,
      )
    }
  }
}

import http from 'node:http'
import { PassThrough } from 'node:stream'
import { pathToFileURL } from 'node:url'
import { unpipeAll } from './unpipe.js'

/**
 * A tiny fan-out server. One shared readable stream (`broadcast`) is piped to
 * every connected `/stream` client. `detachAll()` reliably unpipes the stream
 * from all of them at once (used by `POST /detach` and on shutdown).
 */
export function createApp() {
  const broadcast = new PassThrough()
  const destinations = new Set()

  function addDestination(res) {
    destinations.add(res)
    broadcast.pipe(res, { end: false })
    res.on('close', () => {
      destinations.delete(res)
      broadcast.unpipe(res)
    })
    return res
  }

  function detachAll() {
    const passes = unpipeAll(broadcast)
    destinations.clear()
    return passes
  }

  const server = http.createServer(async (req, res) => {
    const { pathname } = new URL(req.url, 'http://localhost')

    if (req.method === 'GET' && pathname === '/health') {
      return json(res, 200, { destinations: destinations.size })
    }

    if (req.method === 'GET' && pathname === '/stream') {
      res.writeHead(200, {
        'content-type': 'text/plain; charset=utf-8',
        'cache-control': 'no-cache',
        connection: 'keep-alive',
      })
      res.flushHeaders()
      addDestination(res)
      return
    }

    if (req.method === 'POST' && pathname === '/publish') {
      const chunks = []
      for await (const chunk of req) chunks.push(chunk)
      broadcast.write(Buffer.concat(chunks))
      return json(res, 202, {
        published: true,
        destinations: destinations.size,
      })
    }

    if (req.method === 'POST' && pathname === '/detach') {
      const passes = detachAll()
      return json(res, 200, { detached: true, passes })
    }

    return json(res, 404, { error: 'not found' })
  })

  server.on('close', () => detachAll())

  return { server, broadcast, destinations, detachAll }
}

function json(res, status, body) {
  res.writeHead(status, { 'content-type': 'application/json' })
  res.end(JSON.stringify(body))
}

/**
 * Start the server on an ephemeral port (or `port` if given) for tests.
 */
export function start(port = 0) {
  const app = createApp()
  return new Promise((resolve) => {
    app.server.listen(port, () => {
      resolve({ ...app, port: app.server.address().port })
    })
  })
}

const isMain =
  process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href

if (isMain) {
  const port = Number(process.env.PORT) || 3000
  const app = createApp()

  app.server.listen(port, () => {
    console.log(`listening on http://localhost:${port}`)
  })

  const shutdown = () => {
    app.detachAll()
    app.server.close(() => process.exit(0))
  }

  process.on('SIGINT', shutdown)
  process.on('SIGTERM', shutdown)
}

