  assert.ok(detached.passes >= 1)
  assert.equal(app.destinations.size, 0)

  await fetch(`${url}/publish`, { method: 'POST', body: 'after' })
  assert.equal(await a.nextChunk(150), TIMEOUT)
  assert.equal(await b.nextChunk(150), TIMEOUT)
